#include <iostream>

void calibrate(int& value, int offset) { value += offset; }
int main() {
    int value{}, offset{};
    if (!(std::cin >> value >> offset)) return 1;
    calibrate(value, offset);
    std::cout << value << ' ';
    calibrate(value, offset);
    std::cout << value << '\n';
}
